{"implementation":"def solve(case):
    payload = case["payload"]
    edges = payload["edges"]
    refinement = payload["refinement"]
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    if not isinstance(refinement, dict):
        raise ValueError("refinement must be a dict")
    for e in edges:
        if len(e) != 3:
            raise ValueError("each edge must be [src, dst, weight]")
        u, v, w = e
        if u not in refinement or v not in refinement:
            raise ValueError("edge node not in refinement")
        if not isinstance(w, (int, float)):
            raise ValueError("weight must be numeric")
    agg = {}
    for u, v, w in edges:
        gu = refinement[u]
        gv = refinement[v]
        key = (gu, gv) if gu <= gv else (gv, gu)
        agg[key] = agg.get(key, 0) + w
    members = {}
    for node, group in refinement.items():
        members.setdefault(group, []).append(node)
    sorted_edges = sorted([[a, b, wt] for (a,b), wt in agg.items()], key=lambda x: (x[0], x[1]))
    sorted_members = sorted([[group, sorted(nodes)] for group, nodes in members.items()], key=lambda x: x[0])
    return {"edges": sorted_edges, "memberships": sorted_members}"}
